SIO-atomic<pre><code>#include "pico/stdlib.h"
#include "hardware/structs/sio.h"

#define PIN_A 2
#define PIN_B 4
#define PIN_C 6

int main() {
    // 1) Mask with several pins
    const uint32_t MASK = (1u&lt;&lt;PIN_A) | (1u&lt;&lt;PIN_B) | (1u&lt;&lt;PIN_C);

    // 2) Ensure SIO function on each pin (needed only once)
    gpio_init(PIN_A);
    gpio_init(PIN_B);
    gpio_init(PIN_C);

    // 3) Direction: output (OE=1) for ALL pins with ONE single instruction
    sio_hw-&gt;gpio_oe_set = MASK;

    while (true) {
        // 4) SET: drives ALL mask pins high in a single operation
        sio_hw-&gt;gpio_set = MASK;
        sleep_ms(500);

        // 5) CLR: drives ALL mask pins low in a single operation
        sio_hw-&gt;gpio_clr = MASK;
        sleep_ms(500);

        // 6) TOGL (XOR): toggles ALL mask pins in a single operation
        sio_hw-&gt;gpio_togl = MASK;
        sleep_ms(500);
    }
}
</code></pre> <p>In the SDK the typical commands are:</p> <ul> <li><code>gpio_set_mask(MASK);</code> → drives the MASK pins high</li> <li><code>gpio_clr_mask(MASK);</code> → drives the MASK pins low</li> <li><code>gpio_xor_mask(MASK);</code> → toggles the MASK pins</li> <li><code>gpio_put_masked(MASK, VALUE);</code> → drives the MASK pins high/low according to VALUE</li> </ul> <p>Example SDK<pre><code>#include "pico/stdlib.h"
#include "hardware/gpio.h"

#define PIN_A 2
#define PIN_B 4
#define PIN_C 6

int main() {
    // 1) Mask with several pins
    const uint32_t MASK = (1u&lt;&lt;2) | (1u&lt;&lt;4) | (1u&lt;&lt;6);

    // 2) Ensure SIO function on each pin (needed only once)
    gpio_init(2);
    gpio_init(4);
    gpio_init(6);

    // 3) Direction: output (OE=1) for ALL pins with ONE single instruction
    gpio_set_dir_out_masked(MASK);

    while (true) {
        gpio_set_mask(MASK);            // high on 2,4,6
        sleep_ms(200);
        gpio_clr_mask(MASK);            // low on 2,4,6
        sleep_ms(200);
        gpio_xor_mask(MASK);            // toggle on 2,4,6
    }
}
</code></pre></p> EXAMPLE1<pre><code>#include "pico/stdlib.h"
#include "hardware/gpio.h"

#define A   0
#define B   1
#define C   2

int main() {
    const uint32_t MASK = (1u&lt;&lt;A) | (1u&lt;&lt;B) | (1u&lt;&lt;C);
    const uint32_t PATTERN = (1u&lt;&lt;C) | (1u&lt;&lt;A);

    gpio_init_mask(MASK);
    gpio_put_masked(MASK, PATTERN);
    gpio_set_dir_masked(MASK, MASK);

    while (true) {
        sleep_ms(500);
        gpio_xor_mask(MASK);
    }
}
</code></pre> EXAMPLE2<pre><code>#include "pico/stdlib.h"
#include "hardware/gpio.h"

#define A   0
#define B   1
#define C   2

int main() {
    const uint32_t MASK = (1u&lt;&lt;0) | (1u&lt;&lt;1) | (1u&lt;&lt;2);
    gpio_init(0); gpio_init(1); gpio_init(2);
    sio_hw-&gt;gpio_oe_set = MASK;                 // outputs
    sio_hw-&gt;gpio_clr    = MASK;                 // clear first
    sio_hw-&gt;gpio_set    = (1u&lt;&lt;2) | (1u&lt;&lt;0);    // load 101

    while (true) {
        sleep_ms(500);
        sio_hw-&gt;gpio_togl = MASK;
    }
}
</code></pre>

Console echo<pre><code>#include "pico/stdlib.h"
#include &lt;stdio.h&gt;

int main() {
    stdio_init_all();
    sleep_ms(2000); // time for USB enumeration

    printf("\n[Pico USB] Connection ready. Type something and press Enter.\n");

    while (true) {
        int ch = getchar_timeout_us(0);
        if (ch != PICO_ERROR_TIMEOUT) {
            printf("Echo: %c\n", (char)ch);
        }
        sleep_ms(10);
    }
}
</code></pre>

Sender code<pre><code>#include "pico/stdlib.h"
#include "hardware/uart.h"
#include &lt;stdio.h&gt;

#define UART_ID uart0
#define BAUD_RATE 115200
#define TX_PIN 0
#define RX_PIN 1

int main() {
    stdio_init_all();

    gpio_set_function(TX_PIN, GPIO_FUNC_UART);
    gpio_set_function(RX_PIN, GPIO_FUNC_UART);

    uart_init(UART_ID, BAUD_RATE);
    uart_set_format(UART_ID, 8, 1, UART_PARITY_NONE);

    printf("[MAIN] Sending messages every second...\n");

    int counter = 0;
    while (true) {
        char msg[64];
        sprintf(msg, "Message %d from MAIN\r\n", counter++);
        uart_puts(UART_ID, msg);
        sleep_ms(1000);
    }
}
</code></pre> <p>Polling: <code>main()</code> checks whether data is available (<code>uart_is_readable()</code>). Simple, but it consumes CPU and can lose data if the CPU stays busy too long (UART FIFO ≈ 16 bytes).</p>

Receiver code<pre><code>#include "pico/stdlib.h"
#include "hardware/uart.h"
#include &lt;stdio.h&gt;

#define BAUD_RATE 115200
#define TX_PIN 0
#define RX_PIN 1

int main() {
    stdio_init_all();

    gpio_set_function(TX_PIN, GPIO_FUNC_UART);
    gpio_set_function(RX_PIN, GPIO_FUNC_UART);

    uart_init(uart0, BAUD_RATE);
    uart_set_format(UART_ID, 8, 1, UART_PARITY_NONE);

    printf("[SUPPORT] Waiting for messages (polling)...\n");

    while (true) {
        if (uart_is_readable(uart0)) {
            char c = uart_getc(uart0);
            printf("%c", c);
        }
    }
}
</code></pre> <p>Interrupts: the hardware calls a handler when a byte arrives; the ISR must be fast and dump the data into a circular buffer in RAM for later processing. Efficient and robust at high baud rates.</p> IRQ receiver code<pre><code>#include "pico/stdlib.h"
#include "hardware/uart.h"
#include "hardware/irq.h"
#include &lt;stdio.h&gt;

#define UART_ID uart0
#define BAUD_RATE 115200
#define TX_PIN 0
#define RX_PIN 1

// Simple circular buffer
#define BUF_SIZE 256
volatile char buffer[BUF_SIZE];
volatile uint16_t head = 0, tail = 0;

static void on_uart_rx(void) {
    while (uart_is_readable(uart0)) {
        char c = uart_getc(uart0);
        buffer[head] = c;
        head = (head + 1) % BUF_SIZE; // no overflow handling, for simplicity
    }
}

int main() {
    stdio_init_all();

    gpio_set_function(TX_PIN, GPIO_FUNC_UART);
    gpio_set_function(RX_PIN, GPIO_FUNC_UART);

    uart_init(uart0, BAUD_RATE);
    uart_set_format(uart0, 8, 1, UART_PARITY_NONE);

    // Configure the UART0 IRQ
    irq_set_exclusive_handler(UART0_IRQ, on_uart_rx);
    irq_set_enabled(UART0_IRQ, true);
    uart_set_irq_enables(uart0, true, false); // RX interrupt ON

    printf("[SUPPORT IRQ] Waiting for data with interrupts...\n");

    while (true) {
        // Drain the buffer to the USB console
        while (tail != head) {
            char c = buffer[tail];
            tail = (tail + 1) % BUF_SIZE;
            printf("%c", c);
        }
        sleep_ms(10);
    }
}
</code></pre>

Register Function <code>UARTx_FR</code> (Flag Register) Shows FIFO and line status (busy, empty, etc.) <code>UARTx_RSR</code> / <code>UARTx_ECR</code> (Receive Status / Error Clear) Contains error flags: <code>FE</code>, <code>PE</code>, <code>BE</code>, <code>OE</code> Bit Name Meaning 0 FE Framing Error — No valid stop bit detected 1 PE Parity Error — Incorrect parity 2 BE Break Error — RX line held low for too long 3 OE Overrun Error — A byte was lost because the FIFO was full Reading UART errors<pre><code>#include "hardware/uart.h"

if (uart_is_readable(uart0)) {
    int c = uart_getc(uart0); // Read a character
    if (uart_get_hw(uart0)-&gt;rsr &amp; (UART_UARTDR_FE_BITS | UART_UARTDR_PE_BITS | UART_UARTDR_OE_BITS)) {
        printf("⚠️ Error detected on UART\n");
        uart_get_hw(uart0)-&gt;rsr = 0; // Clear errors
    }
}
</code></pre>
